SELECT ADMIN_POSITION, AGE, DEPT_CODE, DEPT_NAME, EDUCATION, EMP_CATEGORY, EMP_ID, EMP_STATUS, ETHNICITY, HOSP_DEPT_CODE, HOSP_DEPT_NAME, ID, ID_NUMBER, INSURANCE_CODE, JOB_TITLE, LEVE_START_TIME, LICENSE_NO, NULL AS MOBILE, NULL AS NAME, ORG_CODE, ORG_NAME, NULL AS PK_PSNCL, PRACTICE_QUAL, PROF_TITLE_LEVEL, NULL AS SEX, TECH_TITLE_APPOINT_DATE, WARD_NAME FROM (SELECT ADMIN_POSITION, AGE, DEPT_CODE, DEPT_NAME, EDUCATION, EMP_CATEGORY, EMP_ID, EMP_STATUS, ETHNICITY, HOSP_DEPT_CODE, HOSP_DEPT_NAME, ID, ID_NUMBER, INSURANCE_CODE, JOB_TITLE, LEVE_START_TIME, LICENSE_NO, NULL AS MOBILE, NULL AS NAME, ORG_CODE, ORG_NAME, NULL AS PK_PSNCL, PRACTICE_QUAL, PROF_TITLE_LEVEL, NULL AS SEX, TECH_TITLE_APPOINT_DATE, WARD_NAME FROM HRPSEY656.EMR_HOS_PRACTITIONER WHERE TO_DATE(DATETIME, 'YYYY-MM-DD HH24:MI:SS') >= :1 AND TO_DATE(DATETIME, 'YYYY-MM-DD HH24:MI:SS') < :2 ORDER BY ID) WHERE ROWNUM <= :3